// === BLOCK 2: colors, borders, backgrounds ===
function convertA1ToRange(a1, sheetId) {
  const col = a1.match(/[A-Z]+/g);
  const row = a1.match(/\d+/g).map(Number);
  const colIdx = col.map(c => c.split('').reduce((acc, l) => acc * 26 + (l.charCodeAt(0) - 64), 0) - 1);
  return {
    sheetId,
    startRowIndex: row.length === 2 ? row[0] - 1 : row[0] - 1,
    endRowIndex: row.length === 2 ? row[1] : row[0],
    startColumnIndex: colIdx.length === 2 ? colIdx[0] : colIdx[0],
    endColumnIndex: colIdx.length === 2 ? colIdx[1] + 1 : colIdx[0] + 1,
  };
}

