const sheetId = $('Creating the \'Total_Sales\' file').first().json.sheets[0].properties.sheetId;
const items = $input.all();
const updates = [];

function getCellUpdate(row, colIndex, value, format = null) {
  const base = {
    userEnteredValue: { numberValue: value },
  };
  if (format) {
    base.userEnteredFormat = format;
  }
  return {
    repeatCell: {
      range: {
        sheetId,
        startRowIndex: row - 1,
        endRowIndex: row,
        startColumnIndex: colIndex,
        endColumnIndex: colIndex + 1,
      },
      cell: base,
      fields: format ? "userEnteredValue,userEnteredFormat.numberFormat" : "userEnteredValue",
    },
  };
}

const product_groups = ["Product_A", "Product_B", "Product_C", "Product_D", "Product_O", "Product_I", "Product_F"];
const customer_status = ["new", "returning"];
const columns = { new: { val: 1, perc: 2 }, returning: { val: 3, perc: 4 } }; // B–E
const percentFormat = { numberFormat: { type: "PERCENT", pattern: "0%" } };
const currencyFormat = { numberFormat: { type: "CURRENCY", pattern: "#,##0 zł" } };

const metrics = [
  {
    metrics: "unique_orders_by_status",
    rows: { "Product_A": 5, "Product_B": 38, "Product_C": 71, "Product_D": 104, "Product_O": 137, "Product_I": 170, "Product_F": 203 },
    formatValues: null
  },
  {
    metrics: "quantity_by_status",
    rows: { "Product_A": 6, "Product_B": 39, "Product_C": 72, "Product_D": 105, "Product_O": 138, "Product_I": 171, "Product_F": 204 },
    formatValues: null
  },
  {
    metrics: "sales_by_status",
    rows: { "Product_A": 7, "Product_B": 40, "Product_C": 73, "Product_D": 106, "Product_O": 139, "Product_I": 172, "Product_F": 205 },
    formatValues: currencyFormat
  },
];

for (const { metrics, rows, formatValues } of metrics) {
  for (const group of product_groups) {
    const row = rows[group];
    let sum = 0;
    const values = [];

    for (const status of customer_status) {
      const record = items.find(el =>
        el.json.product_group === group &&
        el.json.metrics === metrics &&
        el.json.division === status
      );
      const val = record ? parseFloat(record.json.value) : 0;
      sum += val;
      values.push({ val, colVal: columns[status].val, colPerc: columns[status].perc });
      updates.push(getCellUpdate(row, columns[status].val, val, formatValues));
    }

    updates.push(getCellUpdate(row, 5, sum, formatValues)); // column F (sum)

    for (const { val, colPerc } of values) {
      const percent = sum > 0 ? val / sum : 0;
      updates.push(getCellUpdate(row, colPerc, percent, percentFormat));
    }
  }
}

return { requests: updates };

