const assignments = [
  "Sales_Rep_1", "Sales_Rep_2", "Sales_Rep_3", "Sales_Rep_4",
  "Sales_Rep_5", "Sales_Rep_6", "Sales_Rep_7", "Sales_Rep_8", "E-commerce_Platform"
];
const kolNom = [1, 3, 5, 7, 9, 11, 13, 15, 17];
const kolPerc = [2, 4, 6, 8, 10, 12, 14, 16, 18];

const percentFormat = { numberFormat: { type: "PERCENT", pattern: "0%" } };
const currencyFormat = { numberFormat: { type: "CURRENCY", pattern: "#,##0 zł" } };

function processAssignment(metrics, rows, useCurrency = false) {
  for (const [group, row] of Object.entries(rows)) {
    let sum = 0;
    const values = [];

    for (let i = 0; i < assignments.length; i++) {
      const przyp = assignments[i];
      const val = parseFloat(items.find(el => el.json.product_group === group && el.json.metrics === metrics && el.json.division === przyp)?.json.value || 0);
      sum += val;
      values.push({ val, colNom: kolNom[i], colPerc: kolPerc[i] });
      updates.push(getCellUpdate(row, kolNom[i], val, useCurrency ? currencyFormat : null));
    }

    updates.push(getCellUpdate(row, 19, sum, useCurrency ? currencyFormat : null));

    for (const { val, colPerc } of values) {
      const percent = sum > 0 ? val / sum : 0;
      updates.push(getCellUpdate(row, colPerc, percent, percentFormat));
    }
  }
}

