  { metrics: "unique_clients_by_Assignment", rows: { "Product_A": 31, "Product_B": 64, "Product_C": 97, "Product_D": 130, "Product_O": 163, "Product_I": 196, "Product_F": 229 } },
];
for (const m of metrics) processAssignment(m.metrics, m.rows, m.currency || false);

// total_sales / sales_processing
const totalSalesRows = { "Product_A": 2, "Product_B": 3, "Product_C": 4, "Product_D": 5, "Product_O": 6, "Product_I": 7, "Product_F": 8 };
const processingRows = { "Product_A": 13, "Product_B": 14, "Product_C": 15, "Product_D": 16, "Product_O": 17, "Product_I": 18, "Product_F": 19 };
let sumTotal = 0, sumProc = 0;

for (const [group, row] of Object.entries(totalSalesRows)) {
  const v = parseFloat(items.find(el => el.json.product_group === group && el.json.metrics === "total_sales")?.json.value || 0);
  sumTotal += v;
  updates.push(getCellUpdate(row, 8, v, currencyFormat));
}
for (const [group, row] of Object.entries(processingRows)) {
  const v = parseFloat(items.find(el => el.json.product_group === group && el.json.metrics === "sales_processing")?.json.value || 0);
  sumProc += v;
  updates.push(getCellUpdate(row, 8, v, currencyFormat));
}
updates.push(getCellUpdate(9, 8, sumTotal, currencyFormat));
updates.push(getCellUpdate(20, 8, sumProc, currencyFormat));

return { requests: updates };

