const product_groups = ["Product_A", "Product_B", "Product_C", "Product_D", "Product_O", "Product_I", "Product_F"];
const categories = [
  { typ: "E-commerce_Platform", colVal: 1, colPerc: 2 },
  { typ: "Key_Account_Manager", colVal: 3, colPerc: 4 },
];

// --- metrics: division E-commerce_Platform/Key_Account_Manager ---
const metrics = [
  {
    metrics: "quantity_by_Key_Account_Manager_E-commerce_Platform",
    rows: { "Product_A": 19, "Product_B": 52, "Product_C": 85, "Product_D": 118, "Product_O": 151, "Product_I": 184, "Product_F": 217 },
    format: null
  },
  {
    metrics: "sales_by_Key_Account_Manager_E-commerce_Platform",
    rows: { "Product_A": 20, "Product_B": 53, "Product_C": 86, "Product_D": 119, "Product_O": 152, "Product_I": 185, "Product_F": 218 },
    format: currencyFormat
  },
  {
    metrics: "unique_orders_by_Key_Account_Manager_E-commerce_Platform",
    rows: { "Product_A": 18, "Product_B": 51, "Product_C": 84, "Product_D": 117, "Product_O": 150, "Product_I": 183, "Product_F": 216 },
    format: null
  },
];

for (const { metrics, rows, format } of metrics) {
  for (const group of product_groups) {
    const row = rows[group];
    let sum = 0;
    const values = [];

    for (const { typ, colVal, colPerc } of categories) {
      const record = items.find(el =>
        el.json.product_group === group &&
        el.json.metrics === metrics &&
        el.json.division === typ
      );
      const val = record ? parseFloat(record.json.value) : 0;
      sum += val;
      values.push({ val, colPerc });
      updates.push(getCellUpdate(row, colVal, val, format));
    }

    updates.push(getCellUpdate(row, 5, sum, format));

    for (const { val, colPerc } of values) {
      const percent = sum > 0 ? val / sum : 0;
      updates.push(getCellUpdate(row, colPerc, percent, percentFormat));
    }
  }
}

// --- METRICS: unique_orders_by_Key_Account_Manager_E-commerce_Platform_and_status ---
const detailedRows = {
  "Product_A": { Key_Account_Manager: 12, E-commerce_Platform: 13 },
  "Product_B": { Key_Account_Manager: 45, E-commerce_Platform: 46 },
  "Product_C": { Key_Account_Manager: 78, E-commerce_Platform: 79 },
  "Product_D": { Key_Account_Manager: 111, E-commerce_Platform: 112 },
  "Product_O": { Key_Account_Manager: 144, E-commerce_Platform: 145 },
  "Product_I": { Key_Account_Manager: 177, E-commerce_Platform: 178 },
  "Product_F": { Key_Account_Manager: 210, E-commerce_Platform: 211 },
};

for (const [group, { Key_Account_Manager: rowKey_Account_Manager, E-commerce_Platform: rowE-commerce_Platform }] of Object.entries(detailedRows)) {
  const values = { Key_Account_Manager: { new: 0, returning: 0 }, E-commerce_Platform: { new: 0, returning: 0 } };

  for (const item of items) {
    const date = item.json;
    if (
      date.metrics === "unique_orders_by_Key_Account_Manager_E-commerce_Platform_and_status" &&
      date.product_group === group &&
      typeof date.division === 'string' &&
      date.division.includes(" | ")
    ) {
      const [channel, status] = date.division.split(" | ").map(x => x.trim());
      if (values[channel] && (status === "new" || status === "returning")) {
        values[channel][status] += parseFloat(date.value);
      }
    }
  }

  for (const type of ["Key_Account_Manager", "E-commerce_Platform"]) {
    const row = typ === "Key_Account_Manager" ? rowKey_Account_Manager : rowE-commerce_Platform;
    const vNew = values[typ].new;
    const vRet = values[typ].returning;
    const sum = vNew + vRet;

    updates.push(getCellUpdate(row, 1, vNew));
    updates.push(getCellUpdate(row, 2, sum > 0 ? vNew / sum : 0, percentFormat));
    updates.push(getCellUpdate(row, 3, vRet));
    updates.push(getCellUpdate(row, 4, sum > 0 ? vRet / sum : 0, percentFormat));
    updates.push(getCellUpdate(row, 5, sum));
  }
}

return { requests: updates };

