const sheetId = $('Creating the \'Total_Sales\' file').first().json.sheets[1].properties.sheetId;
const rows = $input.all().map(e => e.json);

function num(val) {
  const parsed = parseFloat(String(val).replace(/[^0-9,.-]+/g, '').replace(',', '.'));
  return isNaN(parsed) ? 0 : parsed;
}

function getCellUpdate(row, col, value, format = null) {
  const update = {
    repeatCell: {
      range: {
        sheetId,
        startRowIndex: row - 1,
        endRowIndex: row,
        startColumnIndex: col,
        endColumnIndex: col + 1,
      },
      cell: {
        userEnteredValue: Number.isFinite(value) ? { numberValue: value } : { stringValue: value }
      },
      fields: 'userEnteredValue'
    }
  };

  if (format) {
    update.repeatCell.cell.userEnteredFormat = format;
    update.repeatCell.fields += ',userEnteredFormat.numberFormat';
  }

  return update;
}

function fullBorderUpdate(startRow, endRow, startCol, endCol) {
  return {
    updateBorders: {
      range: {
        sheetId,
        startRowIndex: startRow,
        endRowIndex: endRow,
        startColumnIndex: startCol,
        endColumnIndex: endCol,
      },
      top: { style: 'SOLID', width: 1, color: { red: 0, green: 0, blue: 0 } },
      bottom: { style: 'SOLID', width: 1, color: { red: 0, green: 0, blue: 0 } },
      left: { style: 'SOLID', width: 1, color: { red: 0, green: 0, blue: 0 } },
      right: { style: 'SOLID', width: 1, color: { red: 0, green: 0, blue: 0 } },
      innerHorizontal: { style: 'SOLID', width: 1, color: { red: 0, green: 0, blue: 0 } },
      innerVertical: { style: 'SOLID', width: 1, color: { red: 0, green: 0, blue: 0 } }
    }
  };
}

const currencyFormat = { numberFormat: { type: 'CURRENCY', pattern: '#,##0.00 €' } };
const percentFormat = { numberFormat: { type: 'PERCENT', pattern: '0.0%' } };

const types = ["Corporate", "Key Account", "Growth", "Select"];
const table = {
  "Corporate": { row: 4 },
  "Key Account": { row: 5 },
  "Growth": { row: 6 },
  "Select": { row: 7 }
};

const updates = [];

const staticLabels = [
  ["Type", 3, 13], ["No. Clients", 3, 14], ["Share among unique Customers", 3, 15],
  ["Value", 3, 16], ["Sales share", 3, 17],
  ["Corporate (>40.000 €)", 4, 13], ["Key Account (≥20.000 ≤ 40.000 €)", 5, 13], ["Growth (≥5.000 ≤ 20.000 €)", 6, 13], ["Select (≤ 5.000 €)", 7, 13], ["Total", 8, 13]
];

for (const [text, row, col] of staticLabels) {
  updates.push({
    repeatCell: {
      range: {
        sheetId,
        startRowIndex: row - 1,
        endRowIndex: row,
        startColumnIndex: col,
        endColumnIndex: col + 1
      },
      cell: {
        userEnteredValue: { stringValue: text },
        userEnteredFormat: {
          backgroundColor: { red: 0.788, green: 0.855, blue: 0.972 },
          textFormat: { bold: true }
        }
      },
      fields: "userEnteredValue,userEnteredFormat(backgroundColor,textFormat)"
    }
  });
}

let totalClients = 0;
let totalSales = 0;

for (const type of types) {
  const clients = rows.filter(r => r["Customer Level"] === type);
  const sales = clients.reduce((sum, c) => sum + num(c["Total (€)"]), 0);
  const count = clients.length;

  totalClients += count;
  totalSales += sales;

  table[type].clients = count;
  table[type].sales = sales;
}

for (const type of types) {
  const { row, clients, sales } = table[type];
  updates.push(getCellUpdate(row, 14, clients));
  updates.push(getCellUpdate(row, 15, totalClients > 0 ? clients / totalClients : 0, percentFormat));
  updates.push(getCellUpdate(row, 16, sales, currencyFormat));
  updates.push(getCellUpdate(row, 17, totalSales > 0 ? sales / totalSales : 0, percentFormat));
}

updates.push(getCellUpdate(8, 14, totalClients));
updates.push(getCellUpdate(8, 16, totalSales, currencyFormat));

updates.push(fullBorderUpdate(2, 7, 13, 18));
updates.push(fullBorderUpdate(7, 8, 13, 14));
updates.push(fullBorderUpdate(7, 8, 14, 15));
updates.push(fullBorderUpdate(7, 8, 16, 17));

updates.push({
  updateDimensionProperties: {
    range: {
      sheetId,
      dimension: "COLUMNS",
      startIndex: 13,
      endIndex: 14
    },
    properties: {
      pixelSize: 220
    },
    fields: "pixelSize"
  }
});

return { requests: updates };

